// lib/holiday/holidayPlanRegeneration.knownDefect.test.ts
//
// STANDALONE REPRODUCTION — NOT part of the standard suite (deliberately not
// listed in scripts/standard-tests.json). HLG-04/HLG-05 finding:
//
//   Regenerating a holiday plan puts it back to DRAFT but never restarts the
//   draft's eligibility clock. The auto-publish query selects drafts by
//   `created_at < now − 3 days`, and the regeneration upsert never writes
//   `created_at` (or `updated_at`), so a plan created long ago — published,
//   later regenerated by the teacher — is IMMEDIATELY eligible for automatic
//   publication at the next run. The 3-day grace is therefore not a review
//   window for regenerated plans.
//
// Two kinds of test below:
//   1. CHARACTERISATION / REPRODUCTION tests that PASS while the defect exists
//      (they pin today's behaviour with an in-memory model of PostgREST upsert
//      semantics: ON CONFLICT … DO UPDATE sets only the columns supplied). When
//      the defect is fixed they will fail — that is the signal to delete them.
//   2. A `todo` test stating the DESIRED behaviour. node:test reports todo
//      tests without failing the run, so this documents the known failing case
//      without breaking anything.
//
// CONTAINMENT NOTE: since HLG-05 the auto-publish route is disabled by default
// and unscheduled, so this defect has NO effect unless HOLIDAY_AUTO_PUBLISH_ENABLED
// is deliberately set to 'true'. It must be fixed (or the auto-publish mechanism
// deleted) before anyone enables it.
//
// SMALLEST FUTURE CORRECTION (not implemented here; no migration needed —
// `holiday_plans.updated_at` already exists):
//   (a) lib/repositories/learner-intelligence.repository.ts upsertHolidayPlan():
//       add `updated_at: new Date().toISOString()` to the upsert payload
//       (alongside is_published:false / published_at:null), and
//   (b) findDraftHolidayPlansOlderThan(): filter `.lt('updated_at', cutoff)`
//       instead of `.lt('created_at', cutoff)`.
//   Draft rows are only mutated by regeneration, so updated_at is exactly the
//   "draft clock". Add a regression test mirroring the todo below.
//
// Isolated mocks only — no database, no network, no credentials.
// Run: npx tsx --experimental-test-module-mocks --test lib/holiday/holidayPlanRegeneration.knownDefect.test.ts

import { test, before, mock } from 'node:test'
import assert from 'node:assert/strict'

type Op = { table: string; method: string; args: unknown[] }
const ops: Op[] = []

// Minimal fake of the query-builder chain the two repository methods use.
function fakeDb() {
  return {
    from(table: string) {
      const chain = {
        upsert: (payload: unknown, options: unknown) => { ops.push({ table, method: 'upsert', args: [payload, options] }); return Promise.resolve({ error: null }) },
        select: (cols: string) => { ops.push({ table, method: 'select', args: [cols] }); return chain },
        eq: (col: string, val: unknown) => { ops.push({ table, method: 'eq', args: [col, val] }); return chain },
        lt: (col: string, val: unknown) => { ops.push({ table, method: 'lt', args: [col, val] }); return Promise.resolve({ data: [], error: null }) },
      }
      return chain
    },
  }
}

mock.module('@/utils/supabase/service', {
  namedExports: { createServiceClient: () => fakeDb() },
})

let repo: {
  upsertHolidayPlan: (p: Record<string, unknown>) => Promise<void>
  findDraftHolidayPlansOlderThan: (cutoff: string) => Promise<unknown[]>
}

before(async () => {
  const { LearnerIntelligenceRepository } = await import('@/lib/repositories/learner-intelligence.repository')
  repo = new LearnerIntelligenceRepository() as unknown as typeof repo
})

const regenerationPayload = async (): Promise<Record<string, unknown>> => {
  ops.length = 0
  await repo.upsertHolidayPlan({
    student_id: 's-1', teacher_id: 't-1', school_id: null, term: 2, year: 2026,
    holiday_period: 'August Holiday 2026', holiday_days: 28, plan_data: {},
  })
  const upsert = ops.find(o => o.method === 'upsert')
  assert.ok(upsert, 'upsert must be issued')
  assert.deepEqual((upsert!.args[1] as { onConflict: string }).onConflict, 'student_id,term,year')
  return upsert!.args[0] as Record<string, unknown>
}

const draftFilterColumn = async (): Promise<string> => {
  ops.length = 0
  await repo.findDraftHolidayPlansOlderThan(new Date().toISOString())
  const lt = ops.find(o => o.method === 'lt')
  assert.ok(lt, 'the stale-draft query must apply a < filter')
  return lt!.args[0] as string
}

// ── 1. Characterisation / reproduction (passes while the defect exists) ─────

test('CHARACTERISATION: regeneration returns the row to draft but writes no created_at / updated_at', async () => {
  const payload = await regenerationPayload()
  assert.equal(payload.is_published, false)
  assert.equal(payload.published_at, null)
  assert.equal('created_at' in payload, false, 'created_at is never restarted')
  assert.equal('updated_at' in payload, false, 'no draft clock is restarted')
})

test('CHARACTERISATION: the stale-draft query selects on created_at', async () => {
  assert.equal(await draftFilterColumn(), 'created_at')
})

test('REPRODUCTION (known defect): a long-ago plan that is regenerated is immediately eligible for auto-publication', async () => {
  const payload = await regenerationPayload()
  const column = await draftFilterColumn()

  // A plan created 30 days ago, published, then regenerated TODAY.
  const created = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString()
  const before = { created_at: created, updated_at: created, is_published: true, published_at: created } as Record<string, unknown>

  // PostgREST upsert (merge-duplicates): only the supplied columns are replaced.
  const after = { ...before, ...payload }

  const cutoff = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString()
  const isDraft = after.is_published === false
  const eligibleNow = isDraft && (after[column] as string) < cutoff

  assert.equal(isDraft, true, 'regeneration makes it a draft again (intended)')
  assert.equal(eligibleNow, true, 'DEFECT: the regenerated draft is eligible immediately — no 3-day review window')
})

// ── 2. Desired behaviour (todo — documents the known failing case) ──────────

test('DESIRED: a regenerated draft restarts the clock the auto-publish query reads', { todo: 'known defect — see header: reset updated_at on regeneration and filter on it' }, async () => {
  const payload = await regenerationPayload()
  const column = await draftFilterColumn()

  const created = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString()
  const after = { created_at: created, updated_at: created, is_published: true, published_at: created, ...payload } as Record<string, unknown>

  const cutoff = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString()
  const eligibleNow = after.is_published === false && (after[column] as string) < cutoff
  assert.equal(eligibleNow, false, 'a freshly regenerated draft must NOT be immediately eligible')
})
